// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint96 depositAmount, address attackerEOA) public {
        depositAmount = uint96(bound(depositAmount, 1, 1 ether));

        Attacker attacker = new Attacker(c);

        vm.deal(address(attacker), depositAmount);

        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        vm.prank(address(attacker));
        c.withdrawAll();

        uint balC_before = address(c).balance;
        uint balAtt_before = address(attacker).balance;

        vm.prank(address(attacker));
        c.withdrawAll();

        uint balC_after = address(c).balance;
        uint balAtt_after = address(attacker).balance;

        assertTrue(balC_before == balC_after && balAtt_before == balAtt_after, "no funds should be withdrawable a second time");
    }
}

contract Attacker {
    ReentrancyDAO public target;
    bool public entered;

    constructor(ReentrancyDAO _target) payable {
        target = _target;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.withdrawAll();
        }
    }
}
